// Parse high-intent signals from alerts or manual input
const inputData = items[0].json;

// Example structure - adapt to your actual alert format
const leads = [];

// If you have multiple alerts in one payload, loop here
// For manual use: paste one lead per execution or batch
const lead = {
  name: inputData.name || "HNWI Prospect from " + (inputData.source || "LinkedIn/FB"),
  email: inputData.email || "",
  phone: inputData.phone || "",
  sourcesystem: "hnwi-prospection",
  sourcechannel: inputData.channel || "linkedin", // linkedin | facebook | reddit | google-alert
  ingestionmode: "realtime",
  orgid: process.env.ORG_ID || "your-org-id-here",
  budgetrange: inputData.budget || "€1.5M+",
  propertyinterest: inputData.interest || "Luxury villa / finca Mallorca",
  urgency: inputData.urgency || "medium",
  externalid: "hnwi-" + Date.now(),
  notes: inputData.notes || "High-intent signal from public post. Review and qualify.",
  qualification_tier: "warm", // Will be updated by Nexus LLM
  created_at: new Date().toISOString()
};

leads.push(lead);

return leads.map(l => ({ json: l }));
